public class ChainedTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.util.Optional<Config> of(String raw) {
        return java.util.Optional.of(new Config(raw));
    }

    public static void main(String[] args) {
        check("valid port 8080", java.util.Optional.of(8080), Chained.parsePort(of("8080")));
        check("smallest valid port 1", java.util.Optional.of(1), Chained.parsePort(of("1")));
        check("largest valid port 65535", java.util.Optional.of(65535), Chained.parsePort(of("65535")));
        check("empty Optional in -> empty out", java.util.Optional.empty(), Chained.parsePort(java.util.Optional.empty()));
        check("non-numeric text rejected", java.util.Optional.empty(), Chained.parsePort(of("80a")));
        check("empty string rejected", java.util.Optional.empty(), Chained.parsePort(of("")));
        check("port 0 out of range", java.util.Optional.empty(), Chained.parsePort(of("0")));
        check("123456 out of range", java.util.Optional.empty(), Chained.parsePort(of("123456")));
        try {
            check("null value inside Config -> empty", java.util.Optional.empty(),
                    Chained.parsePort(of(null)));
        } catch (RuntimeException e) {
            System.out.println("FAIL  null value inside Config -> empty -- threw " + e.getClass().getSimpleName());
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

