record Config(String value) {}

public class Chained {

    public static java.util.Optional<Integer> parsePort(java.util.Optional<Config> cfg) {
        return cfg.map(Config::value)
                .filter(v -> v.matches("\\d+"))
                .map(Integer::parseInt)
                .filter(port -> port >= 1 && port <= 65535);
    }
}
